-- Nova install bundle: 11 migrations in order. Generated by scripts/build_install_bundle.mjs; do not edit.
-- Run on STAGING first, check, then production. Safe to run twice. Never re-run 20261114001055 or 20261114001136.

-- ===== supabase/business-agents-migration-standalone.sql (sha256 248eacd0420d) =====
-- Business agents: the call and messaging assistant Nova sells to client businesses.
--
-- Until this file, every channel, credential and prompt belonged to Nova's own internal
-- organization (see 20261110233543_launch_unified_messaging_voice.sql), so the agent could only
-- speak as Nova. These tables give EACH client organization its own agent: its own phone number,
-- its own facts, its own conversations. Nova's own agent becomes one row among many.
--
-- Depends on: organizations, is_org_member() (schema-update.sql Stage 4) and
-- voice-agent-migration-standalone.sql (voice_configurations for hours, voice_knowledge_base for
-- approved answers — both already organization-scoped and reused here, not duplicated).
--
-- Safe to re-run: every statement is IF NOT EXISTS or DROP ... IF EXISTS + CREATE. No existing
-- table or row is altered.

CREATE TABLE IF NOT EXISTS business_agents (
  id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id         UUID NOT NULL UNIQUE REFERENCES organizations(id),
  business_name           TEXT NOT NULL,
  agent_name              TEXT NOT NULL DEFAULT 'the assistant',
  industry                TEXT,
  -- The number customers call and text. One number belongs to exactly one business.
  phone_number            TEXT UNIQUE CHECK (phone_number IS NULL OR phone_number ~ '^\+[1-9][0-9]{7,14}$'),
  greeting                TEXT,
  services                TEXT, -- what the business does, in the owner's own words
  service_area            TEXT,
  booking_url             TEXT,
  owner_alert_phone       TEXT, -- where a human is told a customer needs them
  handoff_instructions    TEXT, -- what to do when the agent cannot answer
  never_say               TEXT, -- topics or promises the owner has ruled out
  tone                    TEXT NOT NULL DEFAULT 'friendly',
  sms_enabled             BOOLEAN NOT NULL DEFAULT false,
  voice_enabled           BOOLEAN NOT NULL DEFAULT false,
  voice_provider          TEXT CHECK (voice_provider IS NULL OR voice_provider IN ('elevenlabs', 'retell', 'vapi')),
  voice_provider_agent_id TEXT,
  voice_id                TEXT,
  -- NULL means no spending is authorized for this business: the agent saves messages and
  -- flags them for a human, and never sends. Never defaulted to a number.
  monthly_spend_cap_cents INTEGER CHECK (monthly_spend_cap_cents IS NULL OR monthly_spend_cap_cents > 0),
  status                  TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'paused')),
  created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at              TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS business_agent_threads (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   UUID NOT NULL REFERENCES organizations(id),
  agent_id          UUID NOT NULL REFERENCES business_agents(id) ON DELETE CASCADE,
  channel           TEXT NOT NULL DEFAULT 'sms' CHECK (channel IN ('sms')),
  customer_phone    TEXT NOT NULL,
  opted_out         BOOLEAN NOT NULL DEFAULT false, -- STOP always wins; only START/UNSTOP clears it
  needs_human       BOOLEAN NOT NULL DEFAULT false,
  last_inbound_at   TIMESTAMPTZ,
  last_outbound_at  TIMESTAMPTZ,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (agent_id, channel, customer_phone)
);
CREATE INDEX IF NOT EXISTS business_agent_threads_org_idx ON business_agent_threads (organization_id);

CREATE TABLE IF NOT EXISTS business_agent_messages (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id   UUID NOT NULL REFERENCES organizations(id),
  thread_id         UUID NOT NULL REFERENCES business_agent_threads(id) ON DELETE CASCADE,
  direction         TEXT NOT NULL CHECK (direction IN ('inbound', 'outbound')),
  body              TEXT NOT NULL,
  provider_sid      TEXT, -- the carrier's message id; makes a retried webhook a no-op
  -- received: customer message saved. sent: carrier accepted our reply (acceptance, not delivery).
  -- failed: carrier refused it. held: saved for a human because the agent may not or could not reply.
  state             TEXT NOT NULL DEFAULT 'received' CHECK (state IN ('received', 'sent', 'failed', 'held')),
  held_reason       TEXT,
  model             TEXT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS business_agent_messages_thread_idx ON business_agent_messages (thread_id, created_at);
CREATE INDEX IF NOT EXISTS business_agent_messages_org_idx ON business_agent_messages (organization_id, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS business_agent_messages_sid_idx ON business_agent_messages (provider_sid) WHERE provider_sid IS NOT NULL;

-- Members of a business may read their own agent and conversations. All writes go through the
-- server (service role) after an explicit per-organization permission check; there is no
-- INSERT/UPDATE/DELETE policy on purpose.
ALTER TABLE business_agents ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_agents ON business_agents;
CREATE POLICY members_read_business_agents ON business_agents FOR SELECT TO authenticated USING (is_org_member(organization_id));

ALTER TABLE business_agent_threads ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_agent_threads ON business_agent_threads;
CREATE POLICY members_read_business_agent_threads ON business_agent_threads FOR SELECT TO authenticated USING (is_org_member(organization_id));

ALTER TABLE business_agent_messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_agent_messages ON business_agent_messages;
CREATE POLICY members_read_business_agent_messages ON business_agent_messages FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/business-registration-migration-standalone.sql (sha256 0fb75be64dbe) =====
-- Business registration. Run AFTER revive-proof-migration-standalone.sql. Safe to re-run.
-- 1) A business asks to join (business_registrations). Nothing else is created until a Nova
--    administrator approves it.
-- 2) A new permission, business.manage: set prices, offers, agreement wording, record payments
--    and edit the assistant for ONE organization. Every endpoint behind it is organization-scoped
--    (api/_journey.js, api/_businessAgent.js), which is why it is safe to give to client owners.
--    admin.view is NOT given to client roles: it still guards Nova's own company-wide screens.

CREATE TABLE IF NOT EXISTS business_registrations (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  business_name    TEXT NOT NULL,
  industry_pack    TEXT,                       -- a key from api/_industryPacks.js, or NULL
  contact_name     TEXT NOT NULL,
  email            TEXT NOT NULL,
  phone            TEXT,
  message          TEXT,
  status           TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'declined')),
  organization_id  UUID REFERENCES organizations(id),  -- set as soon as the organization exists
  owner_user_id    UUID,                               -- set once the owner has a login
  owner_access     TEXT CHECK (owner_access IS NULL OR owner_access IN ('existing_login', 'invite_emailed')),
  decided_by       TEXT,
  decided_at       TIMESTAMPTZ,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- The same person asking twice for the same business is one request.
CREATE UNIQUE INDEX IF NOT EXISTS business_registrations_open_idx
  ON business_registrations (lower(email), lower(business_name)) WHERE status = 'pending';
ALTER TABLE business_registrations ENABLE ROW LEVEL SECURITY; -- no policies: server (service role) only

INSERT INTO permissions (key, description) VALUES
  ('business.manage', 'Set prices, offers, agreement wording and the assistant for one organization')
ON CONFLICT (key) DO NOTHING;

INSERT INTO role_permissions (role, permission_id)
SELECT r.role, p.id FROM permissions p,
  (VALUES ('nova_super_admin'), ('nova_admin'), ('client_owner'), ('client_admin')) AS r(role)
WHERE p.key = 'business.manage'
ON CONFLICT DO NOTHING;

-- ===== supabase/customer-journey-migration-standalone.sql (sha256 395b769e09bd) =====
-- Customer journey: the four agents that take one customer from first contact to a closed job
-- for a client business. Front desk → contracts → accounting → finance.
--
-- This is process state layered on the EXISTING customer records, not a second CRM:
--   * the customer is a crm_contacts row,
--   * the opportunity is a crm_deals row (pipeline 'client_sales'),
--   * appointments are voice_calendar_slots rows,
--   * owner decisions are approval_requests rows.
-- What did not exist anywhere: a business's own priced services, its approved offers, the
-- step-by-step journey, its event trail, and the quote / agreement / invoice / receipt / report
-- documents produced along the way. Those are the five tables below.
--
-- Depends on: organizations, is_org_member(), crm-order-audit-migration-standalone.sql,
-- voice-agent-migration-standalone.sql. Safe to re-run. Alters no existing table or row.

-- What a business sells. A price exists for customers only when the owner has approved it.
CREATE TABLE IF NOT EXISTS business_services (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id),
  name             TEXT NOT NULL,
  description      TEXT,
  keywords         TEXT[] NOT NULL DEFAULT '{}', -- words a customer might use for this service
  price_cents      INTEGER CHECK (price_cents IS NULL OR price_cents > 0),
  price_approved   BOOLEAN NOT NULL DEFAULT false,
  deposit_cents    INTEGER CHECK (deposit_cents IS NULL OR deposit_cents > 0),
  terms_text       TEXT,                           -- agreement wording; NULL = no agreement needed
  terms_approved   BOOLEAN NOT NULL DEFAULT false,
  active           BOOLEAN NOT NULL DEFAULT true,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (organization_id, name),
  CHECK (deposit_cents IS NULL OR price_cents IS NULL OR deposit_cents <= price_cents)
);

-- Discounts the owner has approved, and what earns them (for example, a comment on a post).
CREATE TABLE IF NOT EXISTS business_offers (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id),
  trigger_type     TEXT NOT NULL CHECK (trigger_type IN ('social_comment', 'social_like', 'social_follow', 'message', 'web_visit', 'manual')),
  channel          TEXT, -- NULL = any channel
  code             TEXT NOT NULL,
  description      TEXT NOT NULL,
  percent_off      INTEGER NOT NULL CHECK (percent_off BETWEEN 1 AND 100),
  approved         BOOLEAN NOT NULL DEFAULT false,
  active           BOOLEAN NOT NULL DEFAULT true,
  expires_at       TIMESTAMPTZ,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (organization_id, code)
);

CREATE TABLE IF NOT EXISTS journeys (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     UUID NOT NULL REFERENCES organizations(id),
  contact_id          UUID NOT NULL REFERENCES crm_contacts(id),
  deal_id             UUID REFERENCES crm_deals(id),
  service_id          UUID REFERENCES business_services(id),
  offer_id            UUID REFERENCES business_offers(id),
  stage               TEXT NOT NULL DEFAULT 'inquiry' CHECK (stage IN (
                        'inquiry', 'qualified', 'quoted', 'agreed', 'deposit_due', 'scheduling',
                        'scheduled', 'fulfilled', 'balance_due', 'paid', 'closed', 'cancelled')),
  agent               TEXT NOT NULL DEFAULT 'front_desk' CHECK (agent IN ('front_desk', 'contracts', 'accounting', 'finance')),
  waiting_on          TEXT CHECK (waiting_on IS NULL OR waiting_on IN ('customer', 'owner', 'staff', 'provider')),
  waiting_reason      TEXT,
  paused              BOOLEAN NOT NULL DEFAULT false, -- a person has taken over; the agents stand down
  source_channel      TEXT NOT NULL,
  source_event_id     TEXT NOT NULL,                  -- the channel's own id for the first contact
  request_text        TEXT,
  quote_cents         INTEGER,
  discount_cents      INTEGER NOT NULL DEFAULT 0,
  total_cents         INTEGER,
  paid_cents          INTEGER NOT NULL DEFAULT 0,
  slot_id             UUID REFERENCES voice_calendar_slots(id),
  customer_token_hash TEXT NOT NULL,                  -- SHA-256 of the customer's private link token
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  closed_at           TIMESTAMPTZ,
  UNIQUE (organization_id, source_channel, source_event_id) -- a retried first contact is one journey
);
CREATE INDEX IF NOT EXISTS journeys_org_stage_idx ON journeys (organization_id, stage);

-- Every step an agent took, in order. This is the handoff trail the owner sees.
CREATE TABLE IF NOT EXISTS journey_events (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id),
  journey_id       UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
  agent            TEXT NOT NULL CHECK (agent IN ('front_desk', 'contracts', 'accounting', 'finance', 'customer', 'owner')),
  handed_to        TEXT,
  action           TEXT NOT NULL,
  status           TEXT NOT NULL CHECK (status IN ('done', 'waiting_customer', 'waiting_owner', 'waiting_staff', 'blocked', 'failed')),
  detail           JSONB NOT NULL DEFAULT '{}',
  idempotency_key  TEXT NOT NULL UNIQUE, -- repeating a step cannot record or perform it twice
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS journey_events_journey_idx ON journey_events (journey_id, created_at);

CREATE TABLE IF NOT EXISTS journey_documents (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     UUID NOT NULL REFERENCES organizations(id),
  journey_id          UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
  kind                TEXT NOT NULL CHECK (kind IN ('quote', 'agreement', 'deposit_invoice', 'balance_invoice', 'receipt', 'completion', 'owner_report')),
  seq                 INTEGER NOT NULL DEFAULT 1,
  body                TEXT NOT NULL,
  amount_cents        INTEGER,
  status              TEXT NOT NULL DEFAULT 'issued' CHECK (status IN ('issued', 'accepted', 'paid', 'void')),
  accepted_at         TIMESTAMPTZ,
  acceptance_evidence TEXT,
  -- For a receipt: where the payment was confirmed. 'owner_recorded' is a person's entry, never
  -- presented as a provider-verified payment.
  payment_source      TEXT CHECK (payment_source IS NULL OR payment_source IN ('provider_verified', 'owner_recorded')),
  payment_reference   TEXT,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (journey_id, kind, seq)
);

ALTER TABLE business_services ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_services ON business_services;
CREATE POLICY members_read_business_services ON business_services FOR SELECT TO authenticated USING (is_org_member(organization_id));
ALTER TABLE business_offers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_offers ON business_offers;
CREATE POLICY members_read_business_offers ON business_offers FOR SELECT TO authenticated USING (is_org_member(organization_id));
ALTER TABLE journeys ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_journeys ON journeys;
CREATE POLICY members_read_journeys ON journeys FOR SELECT TO authenticated USING (is_org_member(organization_id));
ALTER TABLE journey_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_journey_events ON journey_events;
CREATE POLICY members_read_journey_events ON journey_events FOR SELECT TO authenticated USING (is_org_member(organization_id));
ALTER TABLE journey_documents ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_journey_documents ON journey_documents;
CREATE POLICY members_read_journey_documents ON journey_documents FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/revive-proof-migration-standalone.sql (sha256 0b8f90ce449d) =====
-- Nova Revive and Nova Proof. Run AFTER customer-journey-migration-standalone.sql.
-- Adds one column and one table. Safe to re-run. Changes no existing row.

-- How long before a customer normally needs this service again (a haircut: 21 days; a furnace
-- check: 365). NULL means the service does not repeat on a schedule, so Revive ignores it.
ALTER TABLE business_services ADD COLUMN IF NOT EXISTS return_days INTEGER;
DO $$ BEGIN
  ALTER TABLE business_services ADD CONSTRAINT business_services_return_days_check CHECK (return_days IS NULL OR return_days BETWEEN 1 AND 1825);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- One row per person per reason per step. "blocked" means the message was prepared and NOT sent,
-- with the reason; "sent" is set only after a provider accepted it.
CREATE TABLE IF NOT EXISTS revive_outreach (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id    UUID NOT NULL REFERENCES organizations(id),
  contact_id         UUID NOT NULL REFERENCES crm_contacts(id),
  journey_id         UUID REFERENCES journeys(id) ON DELETE SET NULL,
  kind               TEXT NOT NULL CHECK (kind IN ('overdue', 'cold_lead', 'empty_slot')),
  service_id         UUID REFERENCES business_services(id),
  offer_id           UUID REFERENCES business_offers(id),
  slot_id            UUID REFERENCES voice_calendar_slots(id),
  channel            TEXT CHECK (channel IS NULL OR channel IN ('sms', 'email')),
  status             TEXT NOT NULL CHECK (status IN ('ready', 'sent', 'blocked')),
  blocked_reason     TEXT,
  message            TEXT NOT NULL,
  days_since         INTEGER,
  provider_reference TEXT,
  sent_at            TIMESTAMPTZ,
  idempotency_key    TEXT NOT NULL UNIQUE,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (status <> 'sent' OR provider_reference IS NOT NULL),
  CHECK (status <> 'blocked' OR blocked_reason IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS revive_outreach_org_idx ON revive_outreach (organization_id, created_at);

ALTER TABLE revive_outreach ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_revive_outreach ON revive_outreach;
CREATE POLICY members_read_revive_outreach ON revive_outreach FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/card-payments-migration-standalone.sql (sha256 fcec65bda6f2) =====
-- Card payments for client businesses (Nova system 17).
--
-- One row per business: which Stripe account it connected, and whether Stripe says that account
-- can take payments yet. Customers' card payments are charged directly on the business's own
-- account, so no card, bank or identity detail is stored here or anywhere in Nova. Payments
-- themselves are recorded as journey receipts (journey_documents, payment_source
-- 'provider_verified') by the signed Stripe Connect webhook.
--
-- Depends on: organizations, is_org_member(). Run after customer-journey-migration-standalone.sql
-- and before zz-public-schema-lockdown-standalone.sql. Safe to re-run. Alters no existing table.

CREATE TABLE IF NOT EXISTS business_payment_accounts (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id    UUID NOT NULL UNIQUE REFERENCES organizations(id),
  provider           TEXT NOT NULL DEFAULT 'stripe' CHECK (provider IN ('stripe')),
  account_id         TEXT NOT NULL UNIQUE,              -- Stripe's acct_… id; never a secret key
  account_type       TEXT NOT NULL CHECK (account_type IN ('standard', 'express')),
  livemode           BOOLEAN NOT NULL DEFAULT false,
  charges_enabled    BOOLEAN NOT NULL DEFAULT false,    -- as last reported by Stripe
  payouts_enabled    BOOLEAN NOT NULL DEFAULT false,
  details_submitted  BOOLEAN NOT NULL DEFAULT false,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Members of the business can see its status; only the server (service role) writes it.
ALTER TABLE business_payment_accounts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_payment_accounts ON business_payment_accounts;
CREATE POLICY members_read_business_payment_accounts ON business_payment_accounts FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/outbound-email-migration-standalone.sql (sha256 f414d55da4bb) =====
-- Email from client businesses (Nova systems 20 and 23): Revive come-back emails to customers
-- and the weekly scorecard to the owner.
--
--   * business_agents gets the owner's switch for email, the address replies and the weekly report
--     go to, and the mailing address printed in marketing emails (US law requires one).
--   * crm_contacts gets a random unsubscribe token for the link in every marketing email.
--   * scorecard_sends records each scorecard email the provider accepted, once per business per day.
--
-- Depends on: business-agents-migration-standalone.sql, crm-order-audit-migration-standalone.sql.
-- Run before zz-public-schema-lockdown-standalone.sql. Safe to re-run. Changes no existing row.

ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS email_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS reply_email TEXT;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS mailing_address TEXT;

ALTER TABLE crm_contacts ADD COLUMN IF NOT EXISTS unsubscribe_token TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS crm_contacts_unsubscribe_token_idx ON crm_contacts (unsubscribe_token) WHERE unsubscribe_token IS NOT NULL;

CREATE TABLE IF NOT EXISTS scorecard_sends (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id     UUID NOT NULL REFERENCES organizations(id),
  period_start        DATE NOT NULL,          -- the day it was sent; one scorecard per business per day
  period_end          TIMESTAMPTZ NOT NULL,
  sent_to             TEXT NOT NULL,
  provider_reference  TEXT NOT NULL,          -- set only after the email provider accepted it
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (organization_id, period_start)
);

ALTER TABLE scorecard_sends ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_scorecard_sends ON scorecard_sends;
CREATE POLICY members_read_scorecard_sends ON scorecard_sends FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/team-dispatch-migration-standalone.sql (sha256 aa8245d6d589) =====
-- Team and job dispatch (Nova system 24) and the pay split (system 25).
--
--   * business_workers: the people who do a business's jobs (employees or independent pros). Each
--     gets a private link to a phone page with their jobs; only a SHA-256 of the link is stored.
--   * job_assignments: which worker does which job. "Done" on the worker's phone records the
--     completion evidence through the same journey step the owner uses.
--   * pay_split_rules: each business's own split, approved by the owner. Never defaulted.
--   * pay_split_entries: each person's share of the money actually received on a paid job.
--     A record only: paying anyone is done by a person, who marks it paid out.
--   * journeys.service_address: where the job is, when the customer gives it.
--
-- Depends on: organizations, is_org_member(), customer-journey-migration-standalone.sql.
-- Run before zz-public-schema-lockdown-standalone.sql. Safe to re-run. Changes no existing row.

ALTER TABLE journeys ADD COLUMN IF NOT EXISTS service_address TEXT;

CREATE TABLE IF NOT EXISTS business_workers (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id),
  name             TEXT NOT NULL,
  phone            TEXT,
  email            TEXT,
  kind             TEXT NOT NULL DEFAULT 'contractor' CHECK (kind IN ('employee', 'contractor')),
  active           BOOLEAN NOT NULL DEFAULT true,
  link_token_hash  TEXT UNIQUE,                 -- SHA-256 of the worker's private phone-page link
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS business_workers_org_idx ON business_workers (organization_id);

CREATE TABLE IF NOT EXISTS job_assignments (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id),
  journey_id       UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
  worker_id        UUID NOT NULL REFERENCES business_workers(id),
  status           TEXT NOT NULL DEFAULT 'assigned' CHECK (status IN ('assigned', 'done', 'cancelled')),
  note             TEXT,
  assigned_by      TEXT,
  done_at          TIMESTAMPTZ,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (status <> 'done' OR done_at IS NOT NULL)
);
-- One live assignment per job; reassigning cancels the old one first.
CREATE UNIQUE INDEX IF NOT EXISTS job_assignments_one_live_idx ON job_assignments (journey_id) WHERE status = 'assigned';
CREATE INDEX IF NOT EXISTS job_assignments_worker_idx ON job_assignments (worker_id, status);

CREATE TABLE IF NOT EXISTS pay_split_rules (
  organization_id  UUID PRIMARY KEY REFERENCES organizations(id),
  shares           JSONB NOT NULL,              -- [{ "label": "Pro", "percent": 50, "to_worker": true }, …] totalling 100
  approved         BOOLEAN NOT NULL DEFAULT false,
  approved_by      TEXT,
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS pay_split_entries (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id),
  journey_id       UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
  worker_id        UUID REFERENCES business_workers(id),
  label            TEXT NOT NULL,
  percent          NUMERIC(5,2) NOT NULL CHECK (percent > 0 AND percent <= 100),
  basis_cents      INTEGER NOT NULL CHECK (basis_cents > 0),   -- money actually received on the job
  amount_cents     INTEGER NOT NULL CHECK (amount_cents >= 0),
  rule_snapshot    JSONB NOT NULL,                             -- the approved rule used, as it was
  paid_out_at      TIMESTAMPTZ,
  paid_out_by      TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (journey_id, label)
);
CREATE INDEX IF NOT EXISTS pay_split_entries_org_idx ON pay_split_entries (organization_id, created_at);

ALTER TABLE business_workers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_workers ON business_workers;
CREATE POLICY members_read_business_workers ON business_workers FOR SELECT TO authenticated USING (is_org_member(organization_id));
ALTER TABLE job_assignments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_job_assignments ON job_assignments;
CREATE POLICY members_read_job_assignments ON job_assignments FOR SELECT TO authenticated USING (is_org_member(organization_id));
ALTER TABLE pay_split_rules ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_pay_split_rules ON pay_split_rules;
CREATE POLICY members_read_pay_split_rules ON pay_split_rules FOR SELECT TO authenticated USING (is_org_member(organization_id));
ALTER TABLE pay_split_entries ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_pay_split_entries ON pay_split_entries;
CREATE POLICY members_read_pay_split_entries ON pay_split_entries FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/reviews-migration-standalone.sql (sha256 1dbee6c46905) =====
-- Reviews (Nova system 19): after a paid job, the customer is asked "How did we do, 1 to 5?".
-- 4 or 5 is shown the owner's own review page; 1 to 3 becomes a call for the owner. Nova never
-- writes or posts a review for anyone.
--
--   * business_agents.review_url: the owner's review page (for example their Google review link).
--   * customer_feedback: one row per finished job, with the private rating link's SHA-256 when
--     the question was sent by email or text.
--   * revive_outreach.kind also allows 'review_request' (the question, sent like a come-back message).
--
-- Depends on: business-agents, customer-journey and revive-proof migrations. Run before
-- zz-public-schema-lockdown-standalone.sql. Safe to re-run. Changes no existing row.

ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS review_url TEXT;

CREATE TABLE IF NOT EXISTS customer_feedback (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id    UUID NOT NULL REFERENCES organizations(id),
  journey_id         UUID NOT NULL UNIQUE REFERENCES journeys(id) ON DELETE CASCADE,
  contact_id         UUID REFERENCES crm_contacts(id),
  token_hash         TEXT UNIQUE,
  rating             INTEGER CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  comment            TEXT,
  review_link_given  BOOLEAN NOT NULL DEFAULT false,
  follow_up          TEXT NOT NULL DEFAULT 'none' CHECK (follow_up IN ('none', 'owner_to_call', 'resolved')),
  answered_at        TIMESTAMPTZ,
  resolved_by        TEXT,
  resolved_at        TIMESTAMPTZ,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (rating IS NULL OR answered_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS customer_feedback_org_idx ON customer_feedback (organization_id, created_at);

ALTER TABLE revive_outreach DROP CONSTRAINT IF EXISTS revive_outreach_kind_check;
ALTER TABLE revive_outreach ADD CONSTRAINT revive_outreach_kind_check CHECK (kind IN ('overdue', 'cold_lead', 'empty_slot', 'review_request'));

ALTER TABLE customer_feedback ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_customer_feedback ON customer_feedback;
CREATE POLICY members_read_customer_feedback ON customer_feedback FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/business-channels-migration-standalone.sql (sha256 95559f9b2689) =====
-- Calls and messages for client businesses on every channel (Nova systems 10 to 15).
--
--   * business_agent_threads: one conversation per customer per channel (texts, WhatsApp, RCS,
--     website chat, phone, Apple Messages, Instagram, Facebook), keyed by the channel's own
--     customer reference (a phone number, a chat visitor id, a Meta user id...).
--   * business_agents: how the business's phone is answered (ring the owner first, then the
--     assistant, or the assistant first), whether a missed caller gets a text, and which
--     message channels are connected. Every switch starts OFF.
--   * business_calls: one row per call to a client business's number, with what happened.
--
-- Depends on: business-agents-migration-standalone.sql, customer-journey-migration-standalone.sql.
-- Run before zz-public-schema-lockdown-standalone.sql. Safe to re-run. The only existing rows it
-- touches are text threads, which get their phone number copied into customer_ref.

-- ---- threads on every channel ----------------------------------------------------------------
ALTER TABLE business_agent_threads DROP CONSTRAINT IF EXISTS business_agent_threads_channel_check;
ALTER TABLE business_agent_threads ADD CONSTRAINT business_agent_threads_channel_check
  CHECK (channel IN ('sms', 'whatsapp', 'rcs', 'web_chat', 'voice', 'apple_messages', 'instagram', 'facebook'));
ALTER TABLE business_agent_threads ALTER COLUMN customer_phone DROP NOT NULL;
ALTER TABLE business_agent_threads ADD COLUMN IF NOT EXISTS customer_ref TEXT;
ALTER TABLE business_agent_threads ADD COLUMN IF NOT EXISTS customer_name TEXT;
UPDATE business_agent_threads SET customer_ref = customer_phone WHERE customer_ref IS NULL AND customer_phone IS NOT NULL;
-- Code that only knows the phone number (texts) still gets customer_ref filled in.
CREATE OR REPLACE FUNCTION business_agent_threads_fill_ref() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.customer_ref := COALESCE(NEW.customer_ref, NEW.customer_phone);
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS business_agent_threads_fill_ref ON business_agent_threads;
CREATE TRIGGER business_agent_threads_fill_ref BEFORE INSERT OR UPDATE ON business_agent_threads
  FOR EACH ROW EXECUTE FUNCTION business_agent_threads_fill_ref();
REVOKE ALL ON FUNCTION business_agent_threads_fill_ref() FROM PUBLIC;
ALTER TABLE business_agent_threads ALTER COLUMN customer_ref SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS business_agent_threads_ref_idx ON business_agent_threads (agent_id, channel, customer_ref);
-- Planned cost of each reply we sent (not a bill), so a business never runs past its monthly cap.
ALTER TABLE business_agent_messages ADD COLUMN IF NOT EXISTS estimate_cents INTEGER NOT NULL DEFAULT 0;

-- ---- how calls are answered --------------------------------------------------------------------
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS call_mode TEXT NOT NULL DEFAULT 'off';
ALTER TABLE business_agents DROP CONSTRAINT IF EXISTS business_agents_call_mode_check;
ALTER TABLE business_agents ADD CONSTRAINT business_agents_call_mode_check
  CHECK (call_mode IN ('off', 'forward_only', 'forward_then_assistant', 'assistant_first'));
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS forward_phone TEXT;            -- rung first, E.164
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS ring_seconds INTEGER NOT NULL DEFAULT 20;
ALTER TABLE business_agents DROP CONSTRAINT IF EXISTS business_agents_ring_seconds_check;
ALTER TABLE business_agents ADD CONSTRAINT business_agents_ring_seconds_check CHECK (ring_seconds BETWEEN 5 AND 60);
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS missed_call_text BOOLEAN NOT NULL DEFAULT false;
-- AI answers (api/_aiReply.js): off until switched on; which model provider; the owner's own answers.
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS ai_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS ai_provider TEXT;
ALTER TABLE business_agents DROP CONSTRAINT IF EXISTS business_agents_ai_provider_check;
ALTER TABLE business_agents ADD CONSTRAINT business_agents_ai_provider_check CHECK (ai_provider IS NULL OR ai_provider IN ('anthropic', 'openai', 'google'));
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS faq TEXT;
ALTER TABLE business_agents DROP CONSTRAINT IF EXISTS business_agents_faq_check;
ALTER TABLE business_agents ADD CONSTRAINT business_agents_faq_check CHECK (faq IS NULL OR char_length(faq) <= 4000);

-- A second private link key per request, for links sent by text, chat or email (api/_journey.js
-- customerLink), so sending one never ends the customer's own browser session.
ALTER TABLE journeys ADD COLUMN IF NOT EXISTS customer_link_hash TEXT;

-- Premium voice reuses business_agents.voice_provider ('elevenlabs'; NULL = Nova's own assistant)
-- and voice_provider_agent_id from business-agents-migration-standalone.sql.
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS voice_tool_secret_hash TEXT;  -- SHA-256 of the premium voice tools key

-- ---- message channels ----------------------------------------------------------------------------
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS web_chat_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS whatsapp_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS whatsapp_number TEXT;          -- the approved WhatsApp sender, E.164
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS rcs_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS messaging_service_sid TEXT;    -- Twilio Messaging Service holding the RCS sender
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS apple_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS apple_business_id TEXT;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS facebook_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS instagram_enabled BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS meta_page_id TEXT;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS instagram_account_id TEXT;
ALTER TABLE business_agents ADD COLUMN IF NOT EXISTS meta_token_enc TEXT;           -- page token, encrypted by the server
-- Each sender belongs to one business only, so an incoming message always finds the right one.
CREATE UNIQUE INDEX IF NOT EXISTS business_agents_whatsapp_idx ON business_agents (whatsapp_number) WHERE whatsapp_number IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS business_agents_msgsvc_idx ON business_agents (messaging_service_sid) WHERE messaging_service_sid IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS business_agents_apple_idx ON business_agents (apple_business_id) WHERE apple_business_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS business_agents_meta_page_idx ON business_agents (meta_page_id) WHERE meta_page_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS business_agents_instagram_idx ON business_agents (instagram_account_id) WHERE instagram_account_id IS NOT NULL;

-- ---- the call log ------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS business_calls (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id),
  agent_id         UUID NOT NULL REFERENCES business_agents(id) ON DELETE CASCADE,
  call_sid         TEXT NOT NULL UNIQUE,
  from_phone       TEXT,
  to_phone         TEXT,
  outcome          TEXT NOT NULL DEFAULT 'ringing' CHECK (outcome IN (
                     'ringing',          -- just came in
                     'answered',         -- a person at the business picked up
                     'missed',           -- nobody picked up and the assistant did not take it
                     'assistant',        -- the assistant is or was talking to the caller
                     'link_sent',        -- the caller got a text with their quote and booking link
                     'callback_requested', -- the caller asked for a call back; the owner was told
                     'not_taking_calls')), -- calls are switched off for this business
  journey_id       UUID REFERENCES journeys(id) ON DELETE SET NULL,
  service_id       UUID REFERENCES business_services(id) ON DELETE SET NULL,
  caller_said      JSONB NOT NULL DEFAULT '[]',   -- what the caller said to the assistant, turn by turn
  texted_back      BOOLEAN NOT NULL DEFAULT false, -- a text went out (provider accepted it)
  held_reason      TEXT,                           -- why the assistant or the text did not run
  turns            INTEGER NOT NULL DEFAULT 0 CHECK (turns BETWEEN 0 AND 20),
  estimate_cents   INTEGER NOT NULL DEFAULT 0,     -- planned cost of the call (not a bill)
  started_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  ended_at         TIMESTAMPTZ,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS business_calls_org_idx ON business_calls (organization_id, started_at DESC);

ALTER TABLE business_calls ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS members_read_business_calls ON business_calls;
CREATE POLICY members_read_business_calls ON business_calls FOR SELECT TO authenticated USING (is_org_member(organization_id));

-- ===== supabase/job-photos-migration-standalone.sql (sha256 3b71a94be185) =====
-- Job photos (Nova system 24): before and after photos from the worker's phone page.
-- Run after team-dispatch-migration-standalone.sql and before zz-public-schema-lockdown-standalone.sql.
-- Safe to run twice. The photos themselves live in the PRIVATE storage bucket 'job-photos' (no public
-- address); the server reads them with the service role and gives the owner one-hour links. Also makes
-- the PRIVATE 'nova-intake-files' bucket for the intake form's uploads.
-- Depends on: team-dispatch-migration-standalone.sql (business_workers, job_assignments).

CREATE TABLE IF NOT EXISTS job_photos (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id  UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  journey_id       UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
  assignment_id    UUID NOT NULL REFERENCES job_assignments(id) ON DELETE CASCADE,
  worker_id        UUID REFERENCES business_workers(id) ON DELETE SET NULL,
  kind             TEXT NOT NULL CHECK (kind IN ('before', 'after')),
  storage_path     TEXT NOT NULL UNIQUE,
  content_type     TEXT NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),
  bytes            INTEGER NOT NULL CHECK (bytes > 0 AND bytes <= 2500000),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS job_photos_journey_idx ON job_photos (organization_id, journey_id, created_at);
CREATE INDEX IF NOT EXISTS job_photos_assignment_idx ON job_photos (assignment_id);

ALTER TABLE job_photos ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS job_photos_member_read ON job_photos;
CREATE POLICY job_photos_member_read ON job_photos FOR SELECT USING (is_org_member(organization_id));

-- The private bucket (Supabase only; skipped on a plain PostgreSQL test database).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'storage' AND table_name = 'buckets') THEN
    INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    VALUES ('job-photos', 'job-photos', false, 2500000, ARRAY['image/jpeg', 'image/png', 'image/webp'])
    ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = EXCLUDED.file_size_limit, allowed_mime_types = EXCLUDED.allowed_mime_types;
    -- The intake form's document uploads (api/business-intake.js): PRIVATE, 4 MB, the same file
    -- types the server accepts; staff open them through a five-minute link. Intake uploads fail
    -- until this bucket exists (it existed in neither staging nor production on 2026-11-14).
    INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    VALUES ('nova-intake-files', 'nova-intake-files', false, 4194304, ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'application/pdf',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'text/csv', 'text/plain'])
    ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = EXCLUDED.file_size_limit, allowed_mime_types = EXCLUDED.allowed_mime_types;
  END IF;
END $$;

-- ===== supabase/zz-public-schema-lockdown-standalone.sql (sha256 b9f3d2e47ddb) =====
-- =============================================================================================
-- Public-schema lockdown for every table created by the standalone migrations. RUN LAST.
--
-- WHY: Supabase grants new public-schema tables to the anon and authenticated roles by default,
-- and the anon key is embedded in the browser bundle. A table without row-level security is
-- therefore readable AND writable by anyone with devtools. 47 of the tables below enable RLS
-- nowhere in their own migration file (they are meant to be reached only through the
-- service-role API, which enforces organization scope in code).
--
-- WHAT: for each listed table that exists — enable RLS (no policy = deny for anon/authenticated;
-- the service role bypasses RLS), revoke everything from anon, and revoke every write privilege
-- from authenticated. Existing org-scoped SELECT policies for authenticated members (crm/audit/
-- wave1 tables) are untouched, so direct member reads keep working.
--
-- SAFE TO RERUN. Skips tables that do not exist yet (migration not applied). Touches ONLY the
-- tables listed here; it does not alter any pre-existing production table.
--
-- Verified by: scripts/check_migration_lockdown.mjs (static coverage check). NOT yet run against a
-- live database — after running, confirm with the anon key that a SELECT on e.g. audit_evidence
-- returns 401/permission denied (see docs/NOVA_PILOT_INSTALLATION.md).
-- =============================================================================================
DO $$
DECLARE
  t text;
  tables text[] := ARRAY[
    'academy_certificates',
    'academy_enrollments',
    'academy_exercise_responses',
    'academy_exercises',
    'academy_lesson_progress',
    'academy_lessons',
    'academy_practical_submissions',
    'academy_programs',
    'academy_quiz_attempts',
    'academy_quiz_questions',
    'application_change_requests',
    'application_evaluations',
    'application_events',
    'application_invitations',
    'application_versions',
    'approval_requests',
    'audit_case_pause_events',
    'audit_cases',
    'audit_deliveries',
    'audit_evidence',
    'audit_finding_evidence',
    'audit_findings',
    'audit_outcomes',
    'audit_recommendations',
    'audit_reports',
    'business_agent_messages',
    'business_agent_threads',
    'business_agents',
    'business_calls',
    'job_photos',
    'business_locations',
    'business_offers',
    'business_payment_accounts',
    'business_workers',
    'business_services',
    'businesses',
    'crm_activities',
    'crm_contacts',
    'customer_feedback',
    'crm_deals',
    'crm_proposals',
    'crystal_completion_reviews',
    'crystal_customers',
    'crystal_equipment',
    'crystal_estimates',
    'crystal_feedback',
    'crystal_invoices',
    'crystal_job_assignments',
    'crystal_job_checklist_items',
    'crystal_job_media',
    'crystal_jobs',
    'crystal_properties',
    'crystal_quote_requests',
    'crystal_recurring_schedules',
    'crystal_service_catalog',
    'installation_events',
    'installation_tests',
    'installations',
    'jobs',
    'journey_documents',
    'journey_events',
    'journeys',
    'job_assignments',
    'pay_split_entries',
    'pay_split_rules',
    'marketing_campaigns',
    'marketing_publishing_adapters',
    'marketing_sequence_enrollments',
    'marketing_sequences',
    'marketing_social_accounts',
    'newsletter_subscribers',
    'order_events',
    'orders',
    'pilot_checklist_items',
    'pilot_permissions',
    'pilots',
    'products',
    'revive_outreach',
    'business_registrations',
    'sales_activation_approvals',
    'scorecard_sends',
    'sales_audit_log',
    'sales_commission_entries',
    'sales_commission_events',
    'sales_config',
    'sales_deal_stage_events',
    'sales_deal_verifications',
    'sales_document_events',
    'sales_document_requests',
    'sales_document_templates',
    'sales_document_versions',
    'sales_lead_assignments',
    'sales_lead_keys',
    'sales_notifications',
    'sales_payments',
    'sales_payout_accounts',
    'sales_payout_batches',
    'sales_payouts',
    'sales_product_readiness_history',
    'sales_provider_events',
    'sales_rep_notes',
    'sales_rep_status_history',
    'sales_reps',
    'sales_scope_exceptions',
    'sales_toolkit_items',
    'voice_calendar_slots',
    'voice_call_sessions',
    'voice_call_tool_events',
    'voice_configurations',
    'voice_knowledge_base',
    'wave1_appointments',
    'wave1_conversations',
    'wave1_messages',
    'wave1_org_settings',
    'wave1_source_events',
    'zion_character_assets',
    'zion_facts',
    'zion_journal_entries',
    'zion_revenue_records',
    'zion_review_events',
    'zion_scripts',
    'zion_storyboards',
    'zion_video_ideas',
    'zion_videos'
  ];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
      EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.%I FROM authenticated', t);
    END IF;
  END LOOP;
END
$$;
